impl Document {
    pub(crate) fn compare_physical_dimension(
        &self,
        other: &Document,
        a: &PhysicalDimension,
        b: &PhysicalDimension,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_current_exp() != b.get_current_exp() {
            return Err(format!("{path}: CURRENT_EXP mismatch"));
        }
        if a.get_length_exp() != b.get_length_exp() {
            return Err(format!("{path}: LENGTH_EXP mismatch"));
        }
        if a.get_luminous_intensity_exp() != b.get_luminous_intensity_exp() {
            return Err(format!("{path}: LUMINOUS_INTENSITY_EXP mismatch"));
        }
        if a.get_mass_exp() != b.get_mass_exp() {
            return Err(format!("{path}: MASS_EXP mismatch"));
        }
        if a.get_molar_amount_exp() != b.get_molar_amount_exp() {
            return Err(format!("{path}: MOLAR_AMOUNT_EXP mismatch"));
        }
        if a.get_temperature_exp() != b.get_temperature_exp() {
            return Err(format!("{path}: TEMPERATURE_EXP mismatch"));
        }
        if a.get_time_exp() != b.get_time_exp() {
            return Err(format!("{path}: TIME_EXP mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_physical_dimension_mapping(
        &self,
        _other: &Document,
        a: &PhysicalDimensionMapping,
        b: &PhysicalDimensionMapping,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_physical_dimension_mapping_set(
        &self,
        other: &Document,
        a: &PhysicalDimensionMappingSet,
        b: &PhysicalDimensionMappingSet,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_single_language_unit_names(
        &self,
        other: &Document,
        a: &SingleLanguageUnitNames,
        b: &SingleLanguageUnitNames,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mixed_content_for_unit_names(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_unit(
        &self,
        other: &Document,
        a: &Unit,
        b: &Unit,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_display_name() != b.get_display_name() {
            return Err(format!("{path}: DISPLAY_NAME mismatch"));
        }
        if a.get_factor_si_to_unit() != b.get_factor_si_to_unit() {
            return Err(format!("{path}: FACTOR_SI_TO_UNIT mismatch"));
        }
        if a.get_offset_si_to_unit() != b.get_offset_si_to_unit() {
            return Err(format!("{path}: OFFSET_SI_TO_UNIT mismatch"));
        }
        if a.get_physical_dimension_ref() != b.get_physical_dimension_ref() {
            return Err(format!("{path}: PHYSICAL_DIMENSION_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_unit_group(
        &self,
        other: &Document,
        a: &UnitGroup,
        b: &UnitGroup,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_unit_refs();
        let list_b = b.get_unit_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: UNIT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.UNIT_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }
}
